1	import java.awt.Color;
2	import java.util.ArrayList;
3	import java.util.Arrays;
4	import java.util.HashMap;
5	import java.util.List;
6	import java.util.Random;
7	
8	/**
9	 * Initializing the simulation. It first launches the UI, then builds the appropriate
10	 * objects to run the simulation desired by the user.
11	 *
12	 * IMPORTANT: This is the class that should be called to run the simulation.
13	 *
14	 * @version 2022.03.01
15	 */
16	public class Initializer
17	{
18	    // The default width for the grid.
19	    private static final int DEFAULT_WIDTH = 120;
20	    // The default depth of the grid.
21	    private static final int DEFAULT_DEPTH = 80;
22	    // The default color for plant objects.
23	    private static final Color DEFAULT_PLANT_COLOR = Color.decode("0x006400");
24	    // Default plant name, for now there is just one type of plant so its name is default, this can be changed as the rest of the code is extendable.
25	    private static final String DEFAULT_PLANT_NAME = "plant";
26	    // The default value of if animals' ages must be randomized when thy are created.
27	    private static final boolean RANDOM_ANIMAL_AGE = true;
28	    // The names of available climate change scenarios.
29	    private static final ArrayList<String> CLIMATE_CHANGE_SCENARIO_NAMES = new ArrayList<>(Arrays.asList("none", "low", "medium", "high"));
30	    // False of the simulation starts during the day, true if it starts during the night.
31	    private static final boolean DEFAULT_START_TIME = false;
32	    // The list of colors available for animal objects.
33	    private ArrayList<Color> listOfColorsForAnimals;
34	    // The index of the next color from the list used for an animal.
35	    private int idxOfColorToUseNext;
36	    // List of species to evolve in the field.
37	    private List<Species> speciesToEvolveInSimulation;
38	    // To read habitat related data.
39	    private final HabitatCSVReader habitatReader;
40	    // To read animal related data.
41	    private final AnimalCSVReader animalReader;
42	    // To read plant related data.
43	    private final PlantCSVReader plantReader;
44	    // A Random object to handle random behaviours throughout the class.
45	    private static final Random rand = Randomizer.getRandom();
46	    // A graphical view of the simulation.
47	    private SimulatorView view;
48	    // The plant concentration in the habitat created by the user.
49	    private double habitatPlantConcentration;
50	    // The GUIHandler handling the GUI.
51	    private GUIHandler handler;
52	    // Tool to alert user about any potential error.
53	    private ErrorThrower errorThrower;
54	
55	
56	    /**
57	     * Builds an Initializer object and initializes its field.
58	     */
59	    public Initializer()
60	    {
61	        speciesToEvolveInSimulation = new ArrayList<>();
62	        habitatReader = new HabitatCSVReader();
63	        animalReader = new AnimalCSVReader();
64	        plantReader = new PlantCSVReader();
65	        listOfColorsForAnimals = new ArrayList<>();
66	        errorThrower = new ErrorThrower();
67	
68	        populateAnimalColors();
69	        idxOfColorToUseNext = 0;
70	
71	        openGUI();
72	    }
73	
74	    /**
75	     * Opens the GUI with the list of available animals and habitats extracted
76	     * from the files as well as the list of available climate change scenarios.
77	     */
78	    private void openGUI()
79	    {
80	        ArrayList<String> animalChoices = animalReader.getChoicesList();
81	        ArrayList<String> habitatChoices = habitatReader.getChoicesList();
82	        handler = new GUIHandler(this, animalChoices, habitatChoices, CLIMATE_CHANGE_SCENARIO_NAMES);
83	    }
84	
85	    /**
86	     * Create a simulator with the animals, habitat, and climate change
87	     * scenario asked by the user as well as all other necessary objects
88	     * for the simulation to run. The created Simulator is returned.
89	     *
90	     * @param chosenHabitat (String) The name of the habitat chosen by the user.
91	     * @param animalsToCreate (HashMap<String, Integer>) Keys are the animals' names and values are the number of each animal we need to create.
92	     * @param scenarioName (String) The name of the climate change scenario to implement in the simulation.
93	     * @return (Simulator) The created simulator.
94	     */
95	    public Simulator initializeSimulation(String chosenHabitat, HashMap<String, Integer> animalsToCreate, String scenarioName)
96	    {
97	        SimulationStep simulatorStepCounter = new SimulationStep();
98	        Field field = new Field(DEFAULT_DEPTH, DEFAULT_WIDTH);
99	        ClimateScenarios chosenClimateChangeScenario = createChosenClimateChangeScenario(scenarioName);
100	        Habitat simulationHabitat = createHabitat(chosenHabitat, simulatorStepCounter, chosenClimateChangeScenario);
101	        if (getNumberOfPlants() + getNumberOfAnimals(animalsToCreate) > calculateFieldArea()) {
102	            errorThrower.throwMessage("Too many animals were added for this habitat, please reduce the number of animals and try again");
103	            return null;
104	        }
105	        view = new SimulatorView(DEFAULT_DEPTH, DEFAULT_WIDTH, handler);
106	        populateWithAnimals(animalsToCreate, field);
107	        populateWithPlants(field);
108	        Time timeObject = new Time(simulatorStepCounter, DEFAULT_START_TIME);
109	        return new Simulator(simulationHabitat, timeObject ,speciesToEvolveInSimulation, field, simulatorStepCounter, view);
110	    }
111	
112	    /**
113	     * Read data for the chosen habitat and create a habitat object appropriately.
114	     *
115	     * @param habitatName (String) The name of the chosen habitat.
116	     * @param simulatorStepCounter (SimulationStep) The created SimulationStep object for this simulation to be handed to the Habitat object.
117	     * @param climateChangeScenario (ClimateScenarios) The created ClimateScenarios enum to be handed to the Habitat object.
118	     * @return (Habitat) the created Habitat object.
119	     */
120	    private Habitat createHabitat (String habitatName, SimulationStep simulatorStepCounter, ClimateScenarios climateChangeScenario)
121	    {
122	        if (habitatName != null) {
123	            habitatReader.extractDataFor(habitatName);
124	            Habitat chosenHabitat = new Habitat(simulatorStepCounter, climateChangeScenario ,habitatReader.getSpringTemperatures(), habitatReader.getSummerTemperatures(), habitatReader.getAutumnTemperatures(), habitatReader.getWinterTemperatures());
125	            habitatPlantConcentration = habitatReader.getPlantConcentration();
126	            return chosenHabitat;
127	        }
128	        else {
129	            errorThrower.throwMessage("Habitat name was not specified successfully.");
130	            return null;
131	        }
132	    }
133	
134	    /**
135	     * Populate the simulation with the chosen animals.
136	     * First reading the data relating to each animal,
137	     * then creating and adding to the list of species the right number of each animal.
138	     *
139	     * @param animalsToCreate (HashMap<String, Integer>) The names and number of chosen animals.
140	     * @param field (Field) The field in which the animals will evolve.
141	     */
142	    private void populateWithAnimals(HashMap<String, Integer> animalsToCreate, Field field)
143	    {
144	        idxOfColorToUseNext = 0;
145	        Location freeLocationToPlaceAnimal;
146	
147	        for(String animalName : animalsToCreate.keySet()) {
148	            animalReader.extractDataFor(animalName);
149	            if (animalsToCreate.get(animalName) != 0)
150	            {
151	                // Retrieve appropriate data.
152	                String name = animalReader.getName();
153	                int maximumTemperature = animalReader.getMaximumTemperature();
154	                int minimumTemperature = animalReader.getMinimumTemperature();
155	                int maxAge = animalReader.getMaximumAge();
156	                int breedingAge = animalReader.getBreedingAge();
157	                double breedingProbability = animalReader.getBreedingProbability();
158	                int maxLitterSize = animalReader.getMaxLitterSize();
159	                int nutritionalValue = animalReader.getNutritionalValue();
160	                boolean hibernates = animalReader.canHibernate();
161	                boolean isNocturnal = animalReader.isNocturnal();
162	
163	                if (animalReader.isPredator()) {
164	                    // Predator object should be created, retrieving appropriate data.
165	                    int strength = animalReader.getStrength();
166	
167	                    // Creating the right number of Predator objects.
168	                    for (int i = 0; i < animalsToCreate.get(animalName); i++) {
169	                        freeLocationToPlaceAnimal = findAvailableLocation(field);
170	                        Predator newPredator = new Predator(strength, field, freeLocationToPlaceAnimal, name, maximumTemperature, minimumTemperature, nutritionalValue, breedingProbability, maxAge, breedingAge, maxLitterSize, RANDOM_ANIMAL_AGE, hibernates, isNocturnal);
171	                        speciesToEvolveInSimulation.add(newPredator);
172	                    }
173	                }
174	                else {
175	                    // Animal object should be created
176	                    // Creating the right number of Animal objects.
177	                    for (int i = 0; i < animalsToCreate.get(animalName); i++) {
178	                        freeLocationToPlaceAnimal = findAvailableLocation(field);
179	                        Animal newAnimal = new Animal(field, freeLocationToPlaceAnimal, name, maximumTemperature, minimumTemperature, nutritionalValue, breedingProbability, maxAge, breedingAge, maxLitterSize, RANDOM_ANIMAL_AGE, hibernates, isNocturnal);
180	                        speciesToEvolveInSimulation.add(newAnimal);
181	                    }
182	                }
183	
184	                // Setting the color for this species.
185	                view.setColor(name, listOfColorsForAnimals.get(idxOfColorToUseNext));
186	                idxOfColorToUseNext ++;
187	            }
188	        }
189	    }
190	
191	    /**
192	     * Create the chosen climate change scenario. Scenarios are pre-defined in the enum ClimateScenarios
193	     * as their functions can be changed to better approximate the real scenarios projected by the GIEC.
194	     *
195	     * @param scenarioName (String) The name of the scenario chosen by the user.
196	     * @return (ClimateScenarios) The created ClimateScenarios enum.
197	     */
198	    private ClimateScenarios createChosenClimateChangeScenario(String scenarioName)
199	    {
200	        ClimateScenarios chosenScenario;
201	        if (scenarioName.equals(CLIMATE_CHANGE_SCENARIO_NAMES.get(3))) {
202	            chosenScenario = ClimateScenarios.SCENARIO4;
203	        }
204	        else if (scenarioName.equals(CLIMATE_CHANGE_SCENARIO_NAMES.get(2))) {
205	            chosenScenario = ClimateScenarios.SCENARIO3;
206	        }
207	        else if (scenarioName.equals(CLIMATE_CHANGE_SCENARIO_NAMES.get(1))) {
208	            chosenScenario = ClimateScenarios.SCENARIO2;
209	        }
210	        else{
211	            chosenScenario = ClimateScenarios.SCENARIO1;
212	        }
213	        return chosenScenario;
214	    }
215	
216	    /**
217	     * Find an available location for an object to be created in the simulation field.
218	     * The simulation is chosen at random and is changed if the randomly selected cell
219	     * already contains an object.
220	     *
221	     * @param field (Field) The simulation's field.
222	     * @return (Location) the available location found.
223	     */
224	    private Location findAvailableLocation(Field field)
225	    {
226	        int randomWidth = rand.nextInt(DEFAULT_WIDTH);
227	        int randomDepth = rand.nextInt(DEFAULT_DEPTH);
228	        while (field.getObjectAt(randomDepth,randomWidth) != null) {
229	            randomWidth = rand.nextInt(DEFAULT_WIDTH);
230	            randomDepth = rand.nextInt(DEFAULT_DEPTH);
231	        }
232	        return new Location(randomDepth, randomWidth);
233	    }
234	
235	    /**
236	     * Calculate the area of the field to know the number of plants that should be created.
237	     *
238	     * @return (int) The field's area.
239	     */
240	    private int calculateFieldArea()
241	    {
242	        return DEFAULT_WIDTH * DEFAULT_DEPTH;
243	    }
244	
245	    /**
246	     * Populate the simulation with the appropriate number of plants.
247	     *
248	     * @param field (Field) The simulation's field.
249	     */
250	    private void populateWithPlants(Field field)
251	    {
252	        Location freeLocationToPlacePlant;
253	        plantReader.extractDataFor(DEFAULT_PLANT_NAME);
254	        String name = plantReader.getName();
255	        int maximumTemperature = plantReader.getMaximumTemperature();
256	        int minimumTemperature = plantReader.getMinimumTemperature();
257	        int nutritionalValue = plantReader.getNutritionalValue();
258	        double reproductionProbability = plantReader.getReproductionProbability();
259	        int maxHealth = plantReader.getMaxHealth();
260	        for (int i = 0; i< getNumberOfPlants(); i++) {
261	            freeLocationToPlacePlant = findAvailableLocation(field);
262	            Plant createdPlant = new Plant(field, freeLocationToPlacePlant, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability, maxHealth);
263	            speciesToEvolveInSimulation.add(createdPlant);
264	        }
265	        view.setColor(name, DEFAULT_PLANT_COLOR);
266	    }
267	
268	    /**
269	     * Calculate the total number of plants to be created.
270	     *
271	     * @return (int) the number of plants.
272	     */
273	    private int getNumberOfPlants()
274	    {
275	        int fieldArea = calculateFieldArea();
276	        return (int)(fieldArea * habitatPlantConcentration);
277	    }
278	
279	    /**
280	     * Calculate the total number of animals to be created.
281	     *
282	     * @return (int) the number of animals.
283	     */
284	    private int getNumberOfAnimals(HashMap<String, Integer> animalsToCreate)
285	    {
286	        int totalNumber = 0;
287	        for (String animalName : animalsToCreate.keySet()) {
288	            totalNumber += animalsToCreate.get(animalName);
289	        }
290	        return totalNumber;
291	    }
292	
